/**
 * Object storage for uploaded contracts. The API writes; the worker reads for
 * extraction. Keys are `<orgId>/contracts/<contractId>` and are generated by
 * slai, never taken from user input.
 */
import { mkdir, readFile, rm, writeFile } from "node:fs/promises";
import { dirname, isAbsolute, resolve, sep } from "node:path";
import { fileURLToPath } from "node:url";

export interface StorageDriver {
  put(key: string, data: Uint8Array, meta: { contentType: string; sha256: string }): Promise<void>;
  get(key: string): Promise<Uint8Array>;
  delete(key: string): Promise<void>;
}

const KEY = /^[A-Za-z0-9][A-Za-z0-9/_.-]{0,500}$/;

/** Writes files under `root`. For development and single-node self-hosting. */
export function createLocalStorage(root: string): StorageDriver {
  const base = resolve(root);
  const pathOf = (key: string) => {
    if (!KEY.test(key) || key.includes("..")) throw new Error("invalid storage key");
    const p = resolve(base, key);
    if (!p.startsWith(base + sep)) throw new Error("invalid storage key");
    return p;
  };
  return {
    async put(key, data) {
      const p = pathOf(key);
      await mkdir(dirname(p), { recursive: true, mode: 0o700 });
      await writeFile(p, data, { mode: 0o600 });
    },
    async get(key) {
      return new Uint8Array(await readFile(pathOf(key)));
    },
    async delete(key) {
      await rm(pathOf(key), { force: true });
    },
  };
}

/**
 * TODO(storage): a GCS/S3 driver implementing StorageDriver for production:
 * - bucket with uniform access, public access prevention, versioning, and a
 *   retention policy; objects encrypted with a customer-managed KMS key;
 * - `put` sets Content-Type and a `sha256` metadata field, and uses an
 *   if-generation-match/if-none-match precondition so keys are write-once;
 * - credentials from workload identity, never from env keys.
 */
export function createStorage(opts: { driver: string; localDir: string }): StorageDriver {
  if (opts.driver === "local") return createLocalStorage(resolveFromRepoRoot(opts.localDir));
  throw new Error(`storage driver "${opts.driver}" is not implemented (see TODO in packages/db/src/storage.ts)`);
}

const REPO_ROOT = fileURLToPath(new URL("../../../", import.meta.url));

/**
 * Relative STORAGE_LOCAL_DIR values are taken from the repo root (where .env
 * lives), so the API and the worker, which run from different package
 * directories, read and write the same files.
 */
export function resolveFromRepoRoot(dir: string): string {
  return isAbsolute(dir) ? dir : resolve(REPO_ROOT, dir);
}

export const contractStorageKey = (orgId: string, contractId: string) => `${orgId}/contracts/${contractId}`;
